import React from "react";
import {AbsoluteFill, interpolate, useCurrentFrame} from "remotion";
import {C, MONO, Reveal, Stage, useIn} from "./lib/kit";

const STEPS = [
  {t: "Ta voix", s: "push-to-talk"},
  {t: "Transcription", s: "OpenAI"},
  {t: "Agent", s: "OpenAI"},
  {t: "Outils", s: "3 outils"},
  {t: "Réponse", s: "voix TTS"},
];
const W = 270, GAP = 82, X0 = 0, Y = 130;

const Node: React.FC<{i: number; lit: number}> = ({i, lit}) => {
  const e = useIn(24 + i * 14, 14);
  const x = X0 + i * (W + GAP);
  return (
    <g transform={`translate(${x},${Y + (1 - e) * 30})`} opacity={e}>
      <rect width={W} height={170} rx={22} fill={C.panel} stroke={lit > 0.5 ? C.accent : C.line} strokeWidth={lit > 0.5 ? 4 : 2} />
      <text x={W / 2} y={84} textAnchor="middle" fill={C.text} fontSize={40} fontWeight={700}>{STEPS[i].t}</text>
      <text x={W / 2} y={128} textAnchor="middle" fill={C.mute} fontSize={26} fontFamily={MONO}>{STEPS[i].s}</text>
    </g>
  );
};

export default function Scene() {
  const frame = useCurrentFrame();
  const total = 4 * (W + GAP);
  // dot travels once the nodes are in, then loops
  const t = ((frame - 100) % 120 + 120) % 120 / 120;
  const dotX = W / 2 + t * total;
  const started = frame >= 100;
  return (
    <Stage eyebrow="Comment ça marche">
      <Reveal delay={6}><div style={{fontSize: 84, fontWeight: 800, marginTop: 24, letterSpacing: -1}}>De ta voix à sa réponse</div></Reveal>
      <AbsoluteFill style={{padding: "380px 120px 0"}}>
        <svg width={1680} height={420} viewBox="0 0 1680 420">
          {STEPS.slice(0, 4).map((_, i) => {
            const x1 = i * (W + GAP) + W, x2 = (i + 1) * (W + GAP);
            const p = interpolate(frame, [40 + i * 14, 58 + i * 14], [0, 1], {extrapolateLeft: "clamp", extrapolateRight: "clamp"});
            return <g key={i}><line x1={x1} y1={Y + 85} x2={x1 + (x2 - x1) * p} y2={Y + 85} stroke={C.line} strokeWidth={4} /><polygon points={`${x2},${Y + 85} ${x2 - 14},${Y + 76} ${x2 - 14},${Y + 94}`} fill={C.line} opacity={p > 0.95 ? 1 : 0} /></g>;
          })}
          {STEPS.map((_, i) => {
            const cx = i * (W + GAP) + W / 2;
            const lit = started ? Math.max(0, 1 - Math.abs(dotX - cx) / 160) : 0;
            return <Node key={i} i={i} lit={lit} />;
          })}
          {started ? <circle cx={dotX} cy={Y + 85} r={14} fill={C.accent} /> : null}
        </svg>
      </AbsoluteFill>
      <AbsoluteFill style={{padding: "0 120px 96px", justifyContent: "flex-end"}}>
        <Reveal delay={150}><div style={{fontSize: 34, color: C.mute}}>Transcription, agent et voix passent par OpenAI : <span style={{color: C.text}}>le réseau reste nécessaire.</span></div></Reveal>
      </AbsoluteFill>
    </Stage>
  );
}

